INSERT INTO public.personas (id, name, bio, birth_year, death_year) VALUES
  ('a0000000-0000-0000-0000-0000000000d1', 'Donald Trump', 'American businessman and politician who served as the 45th and 47th President of the United States, known for his real estate empire, the Apprentice TV show, and an unconventional political style.', 1946, null),
  ('a0000000-0000-0000-0000-0000000000d2', 'Adolf Hitler', 'Austrian-born German politician who led the Nazi Party, became Chancellor of Germany in 1933, initiated World War II, and orchestrated the Holocaust in which six million Jews and millions of others were murdered.', 1889, 1945),
  ('a0000000-0000-0000-0000-0000000000d3', 'Osama bin Laden', 'Saudi-born militant leader who founded al-Qaeda and masterminded the September 11, 2001 terrorist attacks that killed nearly 3,000 people; killed by US Navy SEALs in Pakistan in 2011.', 1957, 2011),
  ('a0000000-0000-0000-0000-0000000000d4', 'Kim Jong-un', 'Supreme Leader of North Korea since 2011, continuing the Kim dynasty; has overseen nuclear weapons tests, periodic diplomatic contacts, and tight authoritarian control of the country.', 1984, null),
  ('a0000000-0000-0000-0000-0000000000d5', 'Boris Johnson', 'British Conservative politician who served as Mayor of London, led the Brexit campaign, and was Prime Minister 2019–2022 before resigning amid ethics scandals.', 1964, null),
  ('a0000000-0000-0000-0000-0000000000d6', 'Joe Biden', 'American Democratic politician who served as US Senator for Delaware, Vice President under Obama, and 46th President of the United States 2021–2025.', 1942, null),
  ('a0000000-0000-0000-0000-0000000000d7', 'Barack Obama', 'American politician and lawyer who served as the 44th President of the United States 2009–2017, the first African American to hold the office, and Nobel Peace Prize laureate.', 1961, null),
  ('a0000000-0000-0000-0000-0000000000d8', 'Hillary Clinton', 'American politician who served as First Lady, US Senator for New York, Secretary of State, and was the first woman to be nominated for president by a major US party in 2016.', 1947, null),
  ('a0000000-0000-0000-0000-0000000000d9', 'Bill Clinton', 'American Democratic politician who served as Governor of Arkansas and 42nd President of the United States 1993–2001; impeached by the House in 1998 over the Monica Lewinsky affair.', 1946, null),
  ('a0000000-0000-0000-0000-0000000000da', 'George W. Bush', 'American Republican politician who served as Governor of Texas and 43rd President 2001–2009, overseeing the response to 9/11, the Afghanistan War, and the Iraq War.', 1946, null),
  ('a0000000-0000-0000-0000-0000000000db', 'George H.W. Bush', 'American Republican politician who served as CIA Director, Vice President under Reagan, and 41st President 1989–1993, overseeing the end of the Cold War and the Gulf War.', 1924, 2018),
  ('a0000000-0000-0000-0000-0000000000dc', 'Ronald Reagan', 'American actor and Republican politician who served as Governor of California and 40th President 1981–1989, known for supply-side economics and a hard line against the Soviet Union.', 1911, 2004),
  ('a0000000-0000-0000-0000-0000000000dd', 'Jimmy Carter', 'American Democratic politician who served as Governor of Georgia and 39th President 1977–1981; post-presidency known for Habitat for Humanity and international diplomacy; Nobel Peace Prize 2002.', 1924, 2024),
  ('a0000000-0000-0000-0000-0000000000de', 'Gerald Ford', 'American Republican politician who served as VP and succeeded Nixon as 38th President 1974–1977 after Nixon''s resignation; known for pardoning Nixon.', 1913, 2006),
  ('a0000000-0000-0000-0000-0000000000df', 'Richard Nixon', 'American Republican politician and 37th President 1969–1974 who opened relations with China and ended US involvement in Vietnam, but resigned over the Watergate scandal.', 1913, 1994),
  ('a0000000-0000-0000-0000-0000000000e0', 'Lyndon B. Johnson', 'American Democratic politician and 36th President 1963–1969, who signed the Civil Rights Act and Great Society legislation but escalated US involvement in Vietnam.', 1908, 1973),
  ('a0000000-0000-0000-0000-0000000000e1', 'Dwight Eisenhower', 'American military general who commanded Allied forces in WWII and served as 34th President 1953–1961, overseeing post-war prosperity and warning about the military-industrial complex.', 1890, 1969),
  ('a0000000-0000-0000-0000-0000000000e2', 'Harry Truman', 'American Democratic politician and 33rd President 1945–1953, who ordered the atomic bombings of Japan, launched the Marshall Plan, and entered the Korean War.', 1884, 1972),
  ('a0000000-0000-0000-0000-0000000000e3', 'Woodrow Wilson', 'American Democratic politician and 28th President 1913–1921, who led the US through World War I, proposed the League of Nations, and promoted self-determination while maintaining racial segregation.', 1856, 1924),
  ('a0000000-0000-0000-0000-0000000000e4', 'Theodore Roosevelt', 'American Republican politician and 26th President 1901–1909, known for trust-busting, conservation policies, and the Panama Canal; Nobel Peace Prize 1906.', 1858, 1919),
  ('a0000000-0000-0000-0000-0000000000e5', 'William Howard Taft', 'American Republican politician who served as 27th President 1909–1913 and later as Chief Justice of the Supreme Court 1921–1930 — the only person to hold both offices.', 1857, 1930),
  ('a0000000-0000-0000-0000-0000000000e6', 'Alexandria Ocasio-Cortez', 'American Democratic politician and member of Congress representing New York since 2019; one of the youngest women ever elected to Congress; prominent progressive voice.', 1989, null),
  ('a0000000-0000-0000-0000-0000000000e7', 'Bernie Sanders', 'American independent-democratic socialist senator from Vermont who ran for the Democratic presidential nomination in 2016 and 2020, energising a progressive movement.', 1941, null),
  ('a0000000-0000-0000-0000-0000000000e8', 'Nancy Pelosi', 'American Democratic politician who served as Speaker of the House 2007–2011 and 2019–2023, the first woman to hold that office, and a key figure in passing the Affordable Care Act.', 1940, null),
  ('a0000000-0000-0000-0000-0000000000e9', 'Mitch McConnell', 'American Republican senator from Kentucky and Senate Majority Leader who shaped US judicial appointments including three Supreme Court seats during the Trump era.', 1942, null),
  ('a0000000-0000-0000-0000-0000000000ea', 'Mike Pence', 'American Republican politician who served as Governor of Indiana and 48th Vice President under Trump 2017–2021; refused to block Electoral College certification on January 6, 2021.', 1959, null),
  ('a0000000-0000-0000-0000-0000000000eb', 'Kamala Harris', 'American politician who served as District Attorney, California Attorney General, US Senator, and 49th Vice President 2021–2025 — the first woman, Black American, and South Asian American VP.', 1964, null),
  ('a0000000-0000-0000-0000-0000000000ec', 'Ron DeSantis', 'American Republican politician who served as a Navy lawyer, congressman, and Governor of Florida from 2019; ran unsuccessfully for the 2024 Republican presidential nomination.', 1978, null),
  ('a0000000-0000-0000-0000-0000000000ed', 'Nikki Haley', 'American Republican politician who served as Governor of South Carolina and US Ambassador to the United Nations under Trump; ran for the 2024 Republican presidential nomination.', 1972, null),
  ('a0000000-0000-0000-0000-0000000000ee', 'Mitt Romney', 'American Republican politician who served as Governor of Massachusetts, ran as the 2012 Republican presidential nominee, and was a US Senator from Utah known for bipartisan positions.', 1947, null),
  ('a0000000-0000-0000-0000-0000000000ef', 'John McCain', 'American Republican senator and Vietnam War POW who ran as the 2008 Republican presidential nominee and was known for his maverick independence and bipartisanship.', 1936, 2018),
  ('a0000000-0000-0000-0000-0000000000f0', 'Al Gore', 'American Democratic politician who served as VP under Clinton and narrowly lost the 2000 presidential election; became a leading climate activist and won the Nobel Peace Prize in 2007.', 1948, null),
  ('a0000000-0000-0000-0000-0000000000f1', 'John Kerry', 'American Democratic politician who served as a Vietnam veteran, US Senator, 2004 Democratic presidential nominee, and Secretary of State under Obama.', 1943, null),
  ('a0000000-0000-0000-0000-0000000000f2', 'Mike Bloomberg', 'American businessman and politician who founded Bloomberg LP, served three terms as Mayor of New York City, and ran briefly for the 2020 Democratic presidential nomination.', 1942, null),
  ('a0000000-0000-0000-0000-0000000000f3', 'Vladimir Putin', 'Russian politician and former KGB officer who has dominated Russian politics since 1999 as Prime Minister and President, overseeing the annexation of Crimea and the full-scale invasion of Ukraine in 2022.', 1952, null),
  ('a0000000-0000-0000-0000-0000000000f4', 'Xi Jinping', 'Chinese politician who became General Secretary of the Chinese Communist Party in 2012 and President of China in 2013, consolidating unprecedented personal power and pursuing the China Dream.', 1953, null),
  ('a0000000-0000-0000-0000-0000000000f5', 'Emmanuel Macron', 'French politician who founded the centrist En Marche! party and was elected President of France in 2017 at age 39, the youngest president in French history, and re-elected in 2022.', 1977, null),
  ('a0000000-0000-0000-0000-0000000000f6', 'Olaf Scholz', 'German Social Democratic politician who served as Finance Minister and succeeded Angela Merkel as Chancellor of Germany in 2021.', 1958, null),
  ('a0000000-0000-0000-0000-0000000000f7', 'Rishi Sunak', 'British Conservative politician and former hedge fund manager who became Chancellor of the Exchequer and then UK Prime Minister 2022–2024, the first British Asian to hold the office.', 1980, null),
  ('a0000000-0000-0000-0000-0000000000f8', 'Tony Blair', 'British Labour politician who served as Prime Minister 1997–2007, won three general elections, oversaw the Good Friday Agreement, and controversially supported the 2003 Iraq War.', 1953, null),
  ('a0000000-0000-0000-0000-0000000000f9', 'Theresa May', 'British Conservative politician who served as Home Secretary and Prime Minister 2016–2019, leading failed attempts to deliver Brexit after the 2016 referendum.', 1956, null),
  ('a0000000-0000-0000-0000-0000000000fa', 'Silvio Berlusconi', 'Italian media mogul and politician who served as Prime Minister of Italy four times; known for his media empire, legal controversies, and colourful personal life.', 1936, 2023),
  ('a0000000-0000-0000-0000-0000000000fb', 'Nicolas Sarkozy', 'French conservative politician who served as President of France 2007–2012 and was later convicted of corruption and influence-peddling charges.', 1955, null),
  ('a0000000-0000-0000-0000-0000000000fc', 'François Hollande', 'French Socialist politician who served as President of France 2012–2017, overseeing the Paris terrorist attacks of 2015 and declining to run for re-election.', 1954, null),
  ('a0000000-0000-0000-0000-0000000000fd', 'Luiz Inácio Lula da Silva', 'Brazilian left-wing politician who served as President 2003–2011 overseeing economic growth, was jailed for corruption in 2018, had conviction annulled, and returned as President in 2023.', 1945, null),
  ('a0000000-0000-0000-0000-0000000000fe', 'Jair Bolsonaro', 'Brazilian right-wing politician and former army captain who served as President 2019–2022, known for his populist rhetoric and disputed handling of the Covid-19 pandemic.', 1955, null),
  ('a0000000-0000-0000-0000-0000000000ff', 'Narendra Modi', 'Indian politician who served as Chief Minister of Gujarat and became Prime Minister of India in 2014, winning landslide re-elections in 2019 and 2024 on a Hindu nationalist platform.', 1950, null),
  ('a0000000-0000-0000-0000-000000000100', 'Justin Trudeau', 'Canadian Liberal politician and son of Pierre Trudeau who served as Prime Minister of Canada 2015–2025, known for his progressive policies and later declining approval ratings.', 1971, null),
  ('a0000000-0000-0000-0000-000000000101', 'Jacinda Ardern', 'New Zealand Labour politician who served as Prime Minister 2017–2023, the world''s youngest female head of government at the time; praised for her response to the Christchurch mosque attacks.', 1980, null),
  ('a0000000-0000-0000-0000-000000000102', 'Kim Jong-il', 'Supreme Leader of North Korea 1994–2011 who inherited power from his father Kim Il-sung, pursuing nuclear weapons development and ruling through tight totalitarian control.', 1941, 2011),
  ('a0000000-0000-0000-0000-000000000103', 'Kim Il-sung', 'Founder and first Supreme Leader of North Korea, ruling from 1948 until his death in 1994; established a communist dynasty and a personality cult that persists under his descendants.', 1912, 1994),
  ('a0000000-0000-0000-0000-000000000104', 'Hugo Chavez', 'Venezuelan left-wing politician who served as President 1999–2013, nationalising industries, using oil wealth for social programmes, and positioning himself as a regional socialist leader.', 1954, 2013),
  ('a0000000-0000-0000-0000-000000000105', 'Nicolas Maduro', 'Venezuelan politician who succeeded Hugo Chavez as President in 2013, overseeing economic collapse, hyperinflation, mass emigration, and disputed elections.', 1962, null),
  ('a0000000-0000-0000-0000-000000000106', 'Saddam Hussein', 'Iraqi politician who served as President 1979–2003; waged wars against Iran and Kuwait, used chemical weapons against Kurds, and was captured by US forces, tried, and executed in 2006.', 1937, 2006),
  ('a0000000-0000-0000-0000-000000000107', 'Muammar Gaddafi', 'Libyan leader who seized power in 1969 and ruled for 42 years with a blend of pan-Arabism and socialism; killed during the 2011 Libyan civil war.', 1942, 2011),
  ('a0000000-0000-0000-0000-000000000108', 'Hosni Mubarak', 'Egyptian politician who served as President 1981–2011 before being ousted in the Arab Spring revolution; tried for corruption and ordering killings of protesters.', 1928, 2020),
  ('a0000000-0000-0000-0000-000000000109', 'Recep Tayyip Erdogan', 'Turkish politician who served as Prime Minister 2003–2014 and President from 2014, shifting Turkey toward Islamic conservatism and centralising presidential power after a 2017 referendum.', 1954, null),
  ('a0000000-0000-0000-0000-00000000010a', 'Volodymyr Zelensky', 'Ukrainian actor and comedian who became President of Ukraine in 2019; led Ukraine''s resistance against Russia''s full-scale invasion in February 2022, becoming a symbol of national defiance.', 1978, null),
  ('a0000000-0000-0000-0000-00000000010b', 'David Ben-Gurion', 'Zionist leader who declared the independence of Israel in 1948, served as its first Prime Minister, and shaped the nation''s founding institutions and defence forces.', 1886, 1973),
  ('a0000000-0000-0000-0000-00000000010c', 'Benito Mussolini', 'Italian fascist dictator who founded fascism, ruled Italy 1922–1943 as Il Duce, allied with Hitler in World War II, and was executed by partisans in 1945.', 1883, 1945),
  ('a0000000-0000-0000-0000-00000000010d', 'Pol Pot', 'Cambodian communist leader of the Khmer Rouge who ruled Cambodia 1975–1979; his regime murdered an estimated 1.5–2 million people in the Cambodian genocide.', 1925, 1998),
  ('a0000000-0000-0000-0000-00000000010e', 'Idi Amin', 'Ugandan military dictator who seized power in 1971 and ruled until 1979; his regime killed an estimated 100,000–500,000 Ugandans; lived in exile in Saudi Arabia until his death.', 1925, 2003),
  ('a0000000-0000-0000-0000-00000000010f', 'Robert Mugabe', 'Zimbabwean politician who led the liberation movement against white minority rule, served as Prime Minister then President 1980–2017, but presided over economic collapse and violent repression.', 1924, 2019),
  ('a0000000-0000-0000-0000-000000000110', 'Augusto Pinochet', 'Chilean military general who led the 1973 coup against Salvador Allende, ruling Chile as military dictator until 1990; his regime killed and tortured thousands of political opponents.', 1915, 2006),
  ('a0000000-0000-0000-0000-000000000111', 'Francisco Franco', 'Spanish military general who led the Nationalist forces to victory in the Spanish Civil War and ruled Spain as dictator from 1939 until his death in 1975.', 1892, 1975),
  ('a0000000-0000-0000-0000-000000000112', 'Joseph McCarthy', 'American Republican senator from Wisconsin whose aggressive investigations into alleged Communist infiltration of the US government in the early 1950s gave rise to the term ''McCarthyism''.', 1908, 1957),
  ('a0000000-0000-0000-0000-000000000113', 'Abu Bakr al-Baghdadi', 'Iraqi militant leader who declared the Islamic State caliphate in 2014 and served as its self-proclaimed caliph until he died during a US Special Forces raid in Syria in 2019.', 1971, 2019),
  ('a0000000-0000-0000-0000-000000000114', 'Charles Manson', 'American criminal cult leader whose Manson Family murdered nine people in California in 1969; sentenced to death (later commuted to life) and died in prison.', 1934, 2017),
  ('a0000000-0000-0000-0000-000000000115', 'Ted Bundy', 'American serial killer who confessed to murdering 30 women in the 1970s; he escaped custody twice and was executed in Florida''s electric chair in 1989.', 1946, 1989),
  ('a0000000-0000-0000-0000-000000000116', 'Jeffrey Dahmer', 'American serial killer and sex offender who murdered and dismembered 17 men and boys in Wisconsin between 1978 and 1991; murdered in prison in 1994.', 1960, 1994),
  ('a0000000-0000-0000-0000-000000000117', 'Bernie Madoff', 'American financier who ran the largest Ponzi scheme in history, defrauding investors of approximately $65 billion; sentenced to 150 years in prison and died there in 2021.', 1938, 2021),
  ('a0000000-0000-0000-0000-000000000118', 'Harvey Weinstein', 'American film producer who co-founded Miramax and The Weinstein Company; his decades of sexual abuse were exposed in 2017, sparking the global #MeToo movement.', 1952, null),
  ('a0000000-0000-0000-0000-000000000119', 'Jeffrey Epstein', 'American financier and convicted sex offender who ran a sex trafficking network involving minors; arrested in 2019 and died in a federal jail cell in disputed circumstances.', 1953, 2019),
  ('a0000000-0000-0000-0000-00000000011a', 'Pablo Escobar', 'Colombian drug lord who founded the Medellín Cartel and at his peak supplied an estimated 80% of the cocaine entering the United States; killed by security forces in 1993.', 1949, 1993),
  ('a0000000-0000-0000-0000-00000000011b', 'El Chapo', 'Mexican drug lord and leader of the Sinaloa Cartel who escaped from maximum-security prison twice before being extradited to the US, where he was sentenced to life imprisonment in 2019.', 1957, null),
  ('a0000000-0000-0000-0000-00000000011c', 'Queen Elizabeth II', 'British monarch who reigned from 1952 to 2022 — the longest-reigning British monarch and the longest-reigning female head of state in history; a symbol of continuity through vast social change.', 1926, 2022),
  ('a0000000-0000-0000-0000-00000000011d', 'King Charles III', 'British monarch who ascended to the throne following the death of his mother Queen Elizabeth II in September 2022; known for his decades of environmental and architectural advocacy.', 1948, null),
  ('a0000000-0000-0000-0000-00000000011e', 'Prince William', 'British royal, son of King Charles III and the late Princess Diana; served as an RAF search-and-rescue pilot; became Prince of Wales in 2022 and heir apparent to the British throne.', 1982, null),
  ('a0000000-0000-0000-0000-00000000011f', 'Prince Harry', 'British royal, son of King Charles III and Princess Diana; served in Afghanistan; married Meghan Markle in 2018; stepped back from royal duties in 2020 and moved to California.', 1984, null),
  ('a0000000-0000-0000-0000-000000000120', 'Meghan Markle', 'American actress known for the TV show Suits who married Prince Harry in 2018, became Duchess of Sussex, and stepped back from royal duties; co-produced content with Netflix.', 1981, null),
  ('a0000000-0000-0000-0000-000000000121', 'Princess Diana', 'British royal known as the People''s Princess who married Prince Charles in 1981, became a global humanitarian icon, divorced in 1996, and died in a Paris car crash in 1997.', 1961, 1997),
  ('a0000000-0000-0000-0000-000000000122', 'Catherine, Princess of Wales', 'British royal who married Prince William in 2011; mother of three children; known for her charity work and became Princess of Wales in 2022; announced cancer diagnosis in 2024.', 1982, null),
  ('a0000000-0000-0000-0000-000000000123', 'Prince Philip', 'Greek and Danish prince who married Queen Elizabeth II in 1947 and served as Duke of Edinburgh for over 70 years; retired from public duties in 2017 and died in 2021 aged 99.', 1921, 2021),
  ('a0000000-0000-0000-0000-000000000124', 'Princess Anne', 'British royal and daughter of Queen Elizabeth II; an accomplished equestrian who competed in the 1976 Olympics and has been one of the hardest-working members of the royal family.', 1950, null),
  ('a0000000-0000-0000-0000-000000000125', 'Prince Andrew', 'British royal and son of Queen Elizabeth II who served in the Falklands War; his association with Jeffrey Epstein led him to step back from public duties in 2019.', 1960, null),
  ('a0000000-0000-0000-0000-000000000126', 'King Felipe VI', 'King of Spain since 2014 following the abdication of his father Juan Carlos I; a lawyer and former Olympic sailor married to journalist Letizia Ortiz.', 1968, null),
  ('a0000000-0000-0000-0000-000000000127', 'Queen Letizia', 'Spanish journalist and television anchor who married Prince Felipe in 2004, becoming Queen of Spain in 2014; known for her fashion choices and advocacy for mental health.', 1972, null),
  ('a0000000-0000-0000-0000-000000000128', 'King Willem-Alexander', 'King of the Netherlands since 2013 following his mother Queen Beatrix''s abdication; a qualified airline pilot who continues to fly commercial aircraft for KLM.', 1967, null),
  ('a0000000-0000-0000-0000-000000000129', 'King Abdullah II', 'King of Jordan since 1999; a former military officer who has maintained Jordan as a moderate state amid regional conflicts while implementing gradual economic and political reforms.', 1962, null),
  ('a0000000-0000-0000-0000-00000000012a', 'Mohammed bin Salman', 'Saudi Crown Prince and de facto ruler who launched Vision 2030 economic reforms, permitted women to drive, but was implicated by US intelligence in the killing of journalist Jamal Khashoggi in 2018.', 1985, null),
  ('a0000000-0000-0000-0000-00000000012b', 'King Salman', 'King of Saudi Arabia since January 2015 following the death of his brother King Abdullah; has ceded significant power to his son Crown Prince Mohammed bin Salman.', 1935, null),
  ('a0000000-0000-0000-0000-00000000012c', 'Sheikh Mohammed bin Rashid Al Maktoum', 'Ruler of Dubai and Prime Minister of the UAE who transformed Dubai into a global financial and tourism hub through massive infrastructure investments and free-trade zones.', 1949, null),
  ('a0000000-0000-0000-0000-00000000012d', 'Tamim bin Hamad Al Thani', 'Emir of Qatar since 2013 who oversaw the successful delivery of the 2022 FIFA World Cup and maintained Qatar''s independent foreign policy including ties with both Iran and the West.', 1980, null),
  ('a0000000-0000-0000-0000-00000000012e', 'Emperor Naruhito', 'Emperor of Japan since 2019 following the abdication of his father Akihito; a historian and water expert who graduated from Oxford; the 126th Emperor of Japan.', 1960, null),
  ('a0000000-0000-0000-0000-00000000012f', 'Emperor Akihito', 'Emperor of Japan 1989–2019 who abdicated due to health reasons; known for his expressions of remorse for Japan''s wartime actions and for his scientific work in ichthyology.', 1933, null),
  ('a0000000-0000-0000-0000-000000000130', 'Beyoncé', 'American singer, songwriter, and performer who rose to fame with Destiny''s Child and became one of the best-selling music artists of all time with multiple Grammy-winning solo albums.', 1981, null),
  ('a0000000-0000-0000-0000-000000000131', 'Rihanna', 'Barbadian singer and businesswoman who became one of the best-selling music artists of all time; founded Fenty Beauty and Savage X Fenty, making her a billionaire entrepreneur.', 1988, null),
  ('a0000000-0000-0000-0000-000000000132', 'Lady Gaga', 'American singer, songwriter, and actress who burst onto the scene with Just Dance in 2008; known for avant-garde performance art and her Oscar-winning role in A Star Is Born.', 1986, null),
  ('a0000000-0000-0000-0000-000000000133', 'Katy Perry', 'American singer and songwriter known for pop hits like I Kissed a Girl and Roar; became the first artist to have five number-one singles from a single album.', 1984, null),
  ('a0000000-0000-0000-0000-000000000134', 'Adele', 'British singer-songwriter from Tottenham whose albums 19, 21, 25, and 30 have all been multi-million sellers; her album 21 is one of the best-selling albums in recording history.', 1988, null),
  ('a0000000-0000-0000-0000-000000000135', 'Ed Sheeran', 'British singer-songwriter who rose from busking on London streets to become one of the world''s best-selling music artists, holding multiple records on the UK singles chart.', 1991, null),
  ('a0000000-0000-0000-0000-000000000136', 'Justin Bieber', 'Canadian singer who was discovered on YouTube at age 13, became a teen pop phenomenon managed by Scooter Braun, and sold over 100 million records worldwide.', 1994, null),
  ('a0000000-0000-0000-0000-000000000137', 'Ariana Grande', 'American singer and actress who began her career on Nickelodeon before releasing a string of pop hits; survived the 2017 Manchester Arena bombing at her concert and responded with a charity concert.', 1993, null),
  ('a0000000-0000-0000-0000-000000000138', 'Billie Eilish', 'American singer-songwriter who became the youngest artist to win the Grammy ''Big Four'' in a single year; known for her distinctive whisper-pop style and environmental activism.', 2001, null),
  ('a0000000-0000-0000-0000-000000000139', 'Drake', 'Canadian rapper and singer who began as an actor on Degrassi before becoming the best-charting artist in Billboard Hot 100 history with multiple number-one albums.', 1986, null),
  ('a0000000-0000-0000-0000-00000000013a', 'Eminem', 'American rapper from Detroit who became the best-selling rap artist of all time; known for his lyrical complexity and the semi-autobiographical film 8 Mile.', 1972, null),
  ('a0000000-0000-0000-0000-00000000013b', 'Jay-Z', 'American rapper and entrepreneur who co-founded Roc-A-Fella Records and Roc Nation; one of the best-selling music artists of all time and the first hip-hop billionaire.', 1969, null),
  ('a0000000-0000-0000-0000-00000000013c', 'Kanye West', 'American rapper and fashion designer who produced albums for Jay-Z before releasing his own critically acclaimed solo albums; later legally changed his name to Ye and made controversial political statements.', 1977, null),
  ('a0000000-0000-0000-0000-00000000013d', 'Nicki Minaj', 'Trinidadian-American rapper and singer who became one of the best-selling female rap artists of all time, known for her colourful wigs and rapid-fire lyrical delivery.', 1982, null),
  ('a0000000-0000-0000-0000-00000000013e', 'Post Malone', 'American rapper and singer known for blending hip-hop with rock and country; his debut album achieved diamond certification, making him one of the most-streamed artists in history.', 1995, null),
  ('a0000000-0000-0000-0000-00000000013f', 'The Weeknd', 'Canadian singer and songwriter Abel Tesfaye who gained fame for his dark R&B mixtapes; his Super Bowl halftime show in 2021 was watched by over 96 million viewers.', 1990, null),
  ('a0000000-0000-0000-0000-000000000140', 'Bruno Mars', 'American singer-songwriter and multi-instrumentalist from Hawaii known for funk-pop hits; won a record-tying six Grammy Awards in one night in 2018.', 1985, null),
  ('a0000000-0000-0000-0000-000000000141', 'Harry Styles', 'British singer who rose to fame as a member of One Direction before launching a critically acclaimed solo career and acting in films including Dunkirk and Don''t Worry Darling.', 1994, null),
  ('a0000000-0000-0000-0000-000000000142', 'Dua Lipa', 'Albanian-British singer and model who became a global pop star with hits from her self-titled debut and the disco-influenced Future Nostalgia album.', 1995, null),
  ('a0000000-0000-0000-0000-000000000143', 'Chris Martin', 'British singer-songwriter and lead vocalist of Coldplay, one of the world''s best-selling music groups; known for anthemic stadium rock and progressive performances.', 1977, null),
  ('a0000000-0000-0000-0000-000000000144', 'Bono', 'Irish singer and humanitarian who fronts U2, one of the world''s best-selling bands; co-founded the ONE Campaign and RED Initiative to fight extreme poverty and AIDS in Africa.', 1960, null),
  ('a0000000-0000-0000-0000-000000000145', 'Thom Yorke', 'British musician and lead singer of Radiohead, known for experimental albums including OK Computer and Kid A that expanded the sonic possibilities of rock music.', 1968, null),
  ('a0000000-0000-0000-0000-000000000146', 'Whitney Houston', 'American singer and actress widely considered the greatest vocalist of all time; sold over 200 million records worldwide but struggled with drug addiction and died aged 48.', 1963, 2012),
  ('a0000000-0000-0000-0000-000000000147', 'Mariah Carey', 'American singer-songwriter with a five-octave vocal range; her Christmas single All I Want for Christmas Is You is one of the best-selling singles in history.', 1969, null),
  ('a0000000-0000-0000-0000-000000000148', 'Céline Dion', 'Canadian singer who became a global superstar after recording the theme for Titanic; performed a long-running Las Vegas residency and was diagnosed with stiff-person syndrome in 2022.', 1968, null),
  ('a0000000-0000-0000-0000-000000000149', 'Britney Spears', 'American pop icon who debuted aged 16 with ...Baby One More Time; her life became tabloid fodder and she was subject to a controversial legal conservatorship from 2008 to 2021.', 1981, null),
  ('a0000000-0000-0000-0000-00000000014a', 'Christina Aguilera', 'American singer and voice coach who debuted the same year as Britney Spears; known for her powerful vocal range and the albums Back to Basics and Stripped.', 1980, null),
  ('a0000000-0000-0000-0000-00000000014b', 'AJ McLean', 'American singer and member of the Backstreet Boys, one of the best-selling boy bands of all time with over 100 million records sold; has spoken openly about his struggles with addiction.', 1978, null),
  ('a0000000-0000-0000-0000-00000000014c', 'Justin Timberlake', 'American singer and actor who rose to fame with NSYNC before a successful solo career; performed the controversial 2004 Super Bowl halftime show with Janet Jackson.', 1981, null),
  ('a0000000-0000-0000-0000-00000000014d', 'Victoria Beckham', 'British singer who was Posh Spice in the Spice Girls before becoming a celebrated fashion designer; married to footballer David Beckham.', 1974, null),
  ('a0000000-0000-0000-0000-00000000014e', 'Shakira', 'Colombian singer-songwriter who became the best-selling Latin music artist of all time; known for belly dancing performances and her philanthropic work in education.', 1977, null),
  ('a0000000-0000-0000-0000-00000000014f', 'Jennifer Lopez', 'American singer, actress, and dancer known as J.Lo; became the first person to have a number-one album and number-one film in the same week; starred in blockbusters and reality shows.', 1969, null),
  ('a0000000-0000-0000-0000-000000000150', 'Enrique Iglesias', 'Spanish singer and son of Julio Iglesias who became one of the best-selling Latin music artists of all time with over 180 million records sold.', 1975, null),
  ('a0000000-0000-0000-0000-000000000151', 'Daddy Yankee', 'Puerto Rican reggaeton pioneer known as the King of Reggaeton; his 2004 song Gasolina popularised the genre globally and he retired from music in 2022.', 1977, null),
