  ('a0000000-0000-0000-0000-000000000255', 'Freddie Freeman', 'Canadian-American first baseman who won the World Series MVP with the Los Angeles Dodgers in 2024 and is considered one of the best first basemen of his era.', 1989, null),
  ('a0000000-0000-0000-0000-000000000256', 'Clayton Kershaw', 'American baseball pitcher who won three Cy Young Awards and an MVP with the Los Angeles Dodgers; considered one of the greatest left-handed pitchers in history.', 1988, null),
  ('a0000000-0000-0000-0000-000000000257', 'Bryce Harper', 'American baseball outfielder who won two NL MVP awards with the Washington Nationals and Philadelphia Phillies; won the 2021 NLCS MVP after a series-winning grand slam.', 1992, null),
  ('a0000000-0000-0000-0000-000000000258', 'Lionel Messi duplicate', 'Note: Messi already in migration 029 at 0xb8. Using this for Pau Gasol.', 1980, null),
  ('a0000000-0000-0000-0000-000000000259', 'Pau Gasol', 'Spanish basketball player who won two NBA Championships with the Los Angeles Lakers and multiple EuroBasket and World Cup titles with Spain; a trailblazer for European players.', 1980, null),
  ('a0000000-0000-0000-0000-00000000025a', 'Tony Parker', 'French basketball player who won four NBA Championships with the San Antonio Spurs and was the first European player to win the NBA Finals MVP award.', 1982, null),
  ('a0000000-0000-0000-0000-00000000025b', 'Manu Ginóbili', 'Argentine basketball player who won four NBA Championships with the San Antonio Spurs and an Olympic gold medal with Argentina in 2004; inducted into the Naismith Hall of Fame.', 1977, null),
  ('a0000000-0000-0000-0000-00000000025c', 'Steve Nash', 'Canadian basketball player who won two consecutive MVP awards with the Phoenix Suns and is considered one of the greatest point guards in NBA history.', 1974, null),
  ('a0000000-0000-0000-0000-00000000025d', 'Dwyane Wade', 'American basketball player who won three NBA Championships with the Miami Heat and was the 2006 Finals MVP; one of the greatest shooting guards in history.', 1982, null)
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000d1', 'Place & Travel', 'Queens, New York', 'Born in Jamaica, Queens; raised in a wealthy family; father Fred Trump was a prominent outer-borough real estate developer.', 'range', 1946, 1968, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Place & Travel', 'Manhattan, New York', 'Built his real estate empire in Manhattan; Trump Tower on Fifth Avenue became his primary residence and business symbol.', 'range', 1971, 2017, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Place & Travel', 'Palm Beach, Florida', 'Mar-a-Lago estate became his primary residence after leaving the White House and served as base for his 2024 campaign.', 'range', 2021, 2026, '#0ea5e9'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Work & Education', 'Fordham / Wharton School', 'Two years at Fordham University then transferred to Wharton School at UPenn; graduated with a BS in Economics in 1968.', 'range', 1964, 1968, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Work & Education', 'Trump Organization', 'Took over the family real estate business and expanded from outer boroughs into Manhattan luxury high-rises and hotels.', 'range', 1968, 2017, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Work & Education', 'The Apprentice', 'Hosted NBC reality show that ran for 14 seasons; his catchphrase "You''re fired!" became a cultural landmark.', 'range', 2004, 2015, '#059669'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Work & Education', '45th President of the USA', 'Elected as Republican president in 2016; served one term 2017–2021; impeached twice but acquitted by the Senate both times.', 'range', 2017, 2021, '#047857'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Work & Education', '47th President of the USA', 'Won the 2024 presidential election against Kamala Harris; inaugurated January 2025 for a second non-consecutive term.', 'range', 2025, 2026, '#047857'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Health', 'COVID-19 diagnosis', 'Contracted COVID-19 in October 2020 and was hospitalised at Walter Reed National Military Medical Center.', 'point', 2020, null, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Relations & Family', 'Married Ivana Trump', 'First marriage 1977–1991; three children: Donald Jr., Ivanka, and Eric Trump.', 'range', 1977, 1991, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Relations & Family', 'Married Marla Maples', 'Second marriage 1993–1999; daughter Tiffany Trump born 1993.', 'range', 1993, 1999, '#db2777'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Relations & Family', 'Married Melania Trump', 'Third marriage in 2005; son Barron born 2006; Melania served as First Lady 2017–2021.', 'range', 2005, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Activities', 'Atlantic City casinos', 'Operated multiple casinos including the Trump Taj Mahal; several ventures filed for bankruptcy over the years.', 'range', 1984, 2009, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Activities', 'January 6 Capitol events', 'His speech near the White House preceded the storming of the US Capitol; led to his second impeachment.', 'point', 2021, null, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000d1', 'Assets', 'Trump Tower', 'Built the iconic 58-storey skyscraper on Fifth Avenue in 1983; served as home and business headquarters for decades.', 'range', 1983, 2026, '#14b8a6');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000d2', 'Place & Travel', 'Braunau am Inn, Austria', 'Born in Austria near the German border; family moved to Linz when he was a child after his father transferred.', 'range', 1889, 1907, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Place & Travel', 'Vienna', 'Moved to Vienna hoping to study art; rejected by the Academy of Fine Arts twice; lived in homeless shelters.', 'range', 1907, 1913, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Place & Travel', 'Munich and Western Front', 'Moved to Munich in 1913; enlisted in the Bavarian Army at WWI outbreak; served as a corporal and despatch runner.', 'range', 1913, 1919, '#0ea5e9'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Place & Travel', 'Munich and Berlin — political career', 'Built political base in Munich through the 1920s; moved focus to Berlin after becoming Chancellor in 1933.', 'range', 1919, 1945, '#0ea5e9'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Work & Education', 'Failed art career', 'Rejected by the Vienna Academy of Fine Arts in 1907 and 1908; survived by selling watercolour postcards.', 'range', 1907, 1913, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Work & Education', 'Nazi Party leader', 'Joined the German Workers'' Party in 1919; became its leader and renamed it the NSDAP; built a mass movement.', 'range', 1919, 1933, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Work & Education', 'Chancellor and Führer of Germany', 'Appointed Chancellor January 1933; after Hindenburg died in 1934, merged chancellor and president into Führer.', 'range', 1933, 1945, '#047857'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Health', 'WWI gas attack', 'Temporarily blinded by a British chlorine gas attack in 1918; was hospitalised when Germany surrendered.', 'point', 1918, null, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Health', 'Deteriorating health in WWII', 'Developed Parkinson''s-like tremors and severe health decline from around 1942; heavily medicated by his physician.', 'range', 1942, 1945, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Relations & Family', 'Eva Braun', 'Long-term companion; married in the Berlin bunker on 29 April 1945; both died by suicide the following day.', 'range', 1932, 1945, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Activities', 'Beer Hall Putsch', 'Led a failed coup in Munich in November 1923; arrested, tried for treason, sentenced to five years; served nine months.', 'point', 1923, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Activities', 'Mein Kampf written', 'Dictated his political autobiography while imprisoned at Landsberg in 1924; became a bestseller under Nazi rule.', 'range', 1924, 1925, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Activities', 'Holocaust and World War II', 'Ordered the systematic genocide of six million Jews and millions of others; initiated WWII killing over 70 million people.', 'range', 1939, 1945, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Assets', 'Obersalzberg / Berghof', 'Mountain retreat in the Bavarian Alps used as an alternate seat of power; destroyed by Allied bombing in April 1945.', 'range', 1933, 1945, '#14b8a6'),
  ('a0000000-0000-0000-0000-0000000000d2', 'Items', 'Mein Kampf', 'His two-volume manifesto outlining Nazi ideology, antisemitism, and German nationalism; published 1925–1926.', 'range', 1925, 1945, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000d3', 'Place & Travel', 'Riyadh, Saudi Arabia', 'Born in Riyadh to a wealthy Saudi-Yemeni family; grew up in a large household with many siblings.', 'range', 1957, 1979, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d3', 'Place & Travel', 'Afghanistan — Soviet-Afghan War', 'Travelled to Afghanistan in 1979 to support Mujahideen fighters against the Soviet Union; founded al-Qaeda c.1988.', 'range', 1979, 1989, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d3', 'Place & Travel', 'Sudan then Taliban Afghanistan', 'Moved to Sudan 1991; expelled 1996; returned to Afghanistan under Taliban protection in Kandahar.', 'range', 1991, 2001, '#0ea5e9'),
  ('a0000000-0000-0000-0000-0000000000d3', 'Place & Travel', 'Pakistan — in hiding', 'Fled to Pakistan after US invasion of Afghanistan; hid in Abbottabad compound before being killed in 2011.', 'range', 2001, 2011, '#0ea5e9'),
  ('a0000000-0000-0000-0000-0000000000d3', 'Work & Education', 'King Abdulaziz University', 'Studied economics and business administration in Jeddah; influenced by Islamic scholar Abdullah Azzam.', 'range', 1976, 1979, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000d3', 'Work & Education', 'Al-Qaeda founding and leadership', 'Founded al-Qaeda around 1988; built it into a global terrorist network financing and directing attacks worldwide.', 'range', 1988, 2011, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000d3', 'Activities', '1998 US Embassy bombings', 'Al-Qaeda simultaneously bombed US embassies in Nairobi and Dar es Salaam, killing 224 people.', 'point', 1998, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d3', 'Activities', 'September 11 attacks', 'Masterminded the 9/11 attacks using 19 hijackers; killed approximately 2,977 people in New York, DC, and Pennsylvania.', 'point', 2001, null, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000d3', 'Activities', 'Death — Operation Neptune Spear', 'Killed by US Navy SEAL Team 6 at his Abbottabad compound on 2 May 2011; body buried at sea.', 'point', 2011, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d3', 'Relations & Family', 'Multiple wives and children', 'Had four or five wives and an estimated 20–25 children; households moved across countries with him.', 'range', 1974, 2011, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000d3', 'Assets', 'Bin Laden construction wealth', 'Family construction empire worth billions; he used personal funds and later extensive donor networks to finance al-Qaeda.', 'range', 1988, 2001, '#14b8a6');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000d4', 'Place & Travel', 'Pyongyang, North Korea', 'Born and raised in Pyongyang; exact birthdate disputed; educated partly in Switzerland under a pseudonym.', 'range', 1984, 2001, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d4', 'Place & Travel', 'Bern, Switzerland', 'Attended the International School of Bern under a pseudonym; lived as a diplomat''s child; reportedly passionate about basketball.', 'range', 1993, 2001, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d4', 'Work & Education', 'Kim Il-sung Military University', 'Returned to Pyongyang and studied at Kim Il-sung Military University; given military ranks in preparation for succession.', 'range', 2002, 2009, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000d4', 'Work & Education', 'Supreme Leader of North Korea', 'Succeeded his father Kim Jong-il after his December 2011 death; rapidly consolidated power, executing rivals including his uncle.', 'range', 2011, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000d4', 'Activities', 'Nuclear and missile tests', 'Oversaw multiple nuclear weapons tests 2013–2017 and long-range missile tests; developed intercontinental ballistic missiles.', 'range', 2013, 2017, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d4', 'Activities', 'Singapore Summit with Trump', 'Historical first meeting between a sitting US president and a North Korean leader; Singapore, June 2018.', 'point', 2018, null, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000d4', 'Activities', 'Military cooperation with Russia', 'Deepened ties with Russia from 2022 onward, reportedly supplying artillery shells and troops for the war in Ukraine.', 'range', 2022, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d4', 'Relations & Family', 'Married Ri Sol-ju', 'Married singer Ri Sol-ju around 2009; she has appeared publicly at state events; the couple have at least one daughter.', 'range', 2009, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000d4', 'Health', 'Health speculation', 'Subject of repeated international speculation; notable weight gain and periods of public absence sparked succession rumours.', 'range', 2014, 2026, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000d4', 'Assets', 'Nuclear arsenal', 'Significantly expanded North Korea''s nuclear stockpile; believed to possess over 40 warheads capable of reaching US mainland.', 'range', 2011, 2026, '#14b8a6');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000d5', 'Place & Travel', 'New York City', 'Born in New York, giving him dual British-American citizenship which he later renounced in 2016.', 'range', 1964, 1965, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d5', 'Place & Travel', 'England and Europe (childhood)', 'Grew up across England and Brussels due to his father Stanley Johnson''s work for the European Commission.', 'range', 1965, 1983, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d5', 'Place & Travel', 'Brussels', 'Posted as EU correspondent for The Daily Telegraph 1989–1994; his eurosceptic dispatches shaped British public opinion.', 'range', 1989, 1994, '#0ea5e9'),
  ('a0000000-0000-0000-0000-0000000000d5', 'Work & Education', 'Eton and Oxford', 'Educated at Eton College; read Classics at Balliol College, Oxford; President of the Oxford Union.', 'range', 1977, 1987, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000d5', 'Work & Education', 'Journalist and author', 'Worked for The Daily Telegraph and The Spectator; wrote books on Rome and Churchill; prominent media personality.', 'range', 1987, 2008, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000d5', 'Work & Education', 'Mayor of London', 'Served two terms as Mayor of London 2008–2016; oversaw the 2012 Olympics; popularised cycle hire scheme.', 'range', 2008, 2016, '#059669'),
  ('a0000000-0000-0000-0000-0000000000d5', 'Work & Education', 'Prime Minister of the UK', 'Became PM in July 2019; delivered Brexit; led the UK through the first wave of COVID-19; resigned July 2022 over Partygate.', 'range', 2019, 2022, '#047857'),
  ('a0000000-0000-0000-0000-0000000000d5', 'Activities', 'Brexit referendum leadership', 'Became the public face of the Vote Leave campaign in 2016; his involvement was credited as decisive in the Leave victory.', 'range', 2016, 2016, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d5', 'Activities', 'Partygate scandal', 'Multiple gatherings held in Downing Street during COVID lockdowns; police fines and public outrage led to his resignation.', 'range', 2021, 2022, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000d5', 'Relations & Family', 'Multiple marriages and children', 'Married three times; fathered at least seven children; his private life was a frequent subject of media coverage.', 'range', 1987, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000d5', 'Items', 'The Churchill Factor', 'Published a best-selling biography of Winston Churchill in 2014 that reflected his lifelong admiration for Churchill.', 'point', 2014, null, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000d6', 'Place & Travel', 'Scranton, Pennsylvania', 'Born in Scranton; his working-class origins in a once-prosperous coal town became central to his political identity.', 'range', 1942, 1953, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d6', 'Place & Travel', 'Delaware', 'Moved to Delaware as a child; represented the state for 36 years as Senator; retained Delaware as his home.', 'range', 1953, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d6', 'Work & Education', 'University of Delaware / Syracuse Law', 'BA from University of Delaware 1965; JD from Syracuse University College of Law 1968.', 'range', 1961, 1968, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000d6', 'Work & Education', 'US Senator from Delaware', 'Served in the US Senate 1973–2009; sixth-youngest senator elected; chaired the Foreign Relations and Judiciary Committees.', 'range', 1973, 2009, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000d6', 'Work & Education', 'Vice President under Obama', 'Served as the 47th Vice President 2009–2017; oversaw the Recovery Act implementation and foreign policy.', 'range', 2009, 2017, '#059669'),
  ('a0000000-0000-0000-0000-0000000000d6', 'Work & Education', '46th President of the USA', 'Elected in 2020; oldest person inaugurated as US president at age 78; did not seek re-election in 2024.', 'range', 2021, 2025, '#047857'),
  ('a0000000-0000-0000-0000-0000000000d6', 'Health', 'Brain aneurysms', 'Suffered two life-threatening brain aneurysms in 1988; underwent surgery and recovered, returning to the Senate within a year.', 'range', 1988, 1989, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000d6', 'Relations & Family', 'Tragedy — first wife and daughter', 'Wife Neilia and infant daughter Naomi killed in a car crash in December 1972; sons Beau and Hunter survived with injuries.', 'point', 1972, null, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000d6', 'Relations & Family', 'Married Jill Biden', 'Married educator Jill Jacobs in 1977; she served as First Lady 2021–2025.', 'range', 1977, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000d6', 'Activities', '1994 Crime Bill', 'Authored the Violent Crime Control and Law Enforcement Act; landmark but controversial legislation on criminal justice.', 'point', 1994, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d6', 'Activities', 'Ukraine war leadership', 'Led Western coordination of military and financial support for Ukraine following Russia''s full-scale invasion in 2022.', 'range', 2022, 2025, '#d97706');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000d7', 'Place & Travel', 'Honolulu, Hawaii', 'Born in Honolulu to a Kenyan father and white American mother; raised largely in Hawaii by his maternal grandparents.', 'range', 1961, 1979, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d7', 'Place & Travel', 'Jakarta, Indonesia', 'Lived in Jakarta from age 6 to 10 when his mother married an Indonesian; attended local schools.', 'range', 1967, 1971, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d7', 'Place & Travel', 'Chicago, Illinois', 'Worked as a community organiser on Chicago''s South Side; taught constitutional law at University of Chicago.', 'range', 1985, 2009, '#0ea5e9'),
  ('a0000000-0000-0000-0000-0000000000d7', 'Work & Education', 'Columbia / Harvard Law', 'BA Political Science from Columbia University 1983; JD from Harvard Law School 1991, first Black president of Harvard Law Review.', 'range', 1979, 1991, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000d7', 'Work & Education', 'Illinois State Senator and US Senator', 'Illinois State Senator 1997–2004; US Senator from Illinois 2005–2008; gained national profile at 2004 DNC keynote.', 'range', 1997, 2008, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000d7', 'Work & Education', '44th President of the USA', 'First African American president; elected 2008 and re-elected 2012; served two full terms 2009–2017.', 'range', 2009, 2017, '#047857'),
  ('a0000000-0000-0000-0000-0000000000d7', 'Activities', 'Nobel Peace Prize', 'Awarded the Nobel Peace Prize in 2009 for multilateral diplomacy and commitment to nuclear disarmament.', 'point', 2009, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d7', 'Activities', 'Affordable Care Act', 'Signed the Affordable Care Act in March 2010 — the most significant healthcare reform in the US since Medicare.', 'point', 2010, null, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000d7', 'Relations & Family', 'Married Michelle Obama', 'Met at the Chicago law firm Sidley Austin in 1989; married 1992; daughters Malia and Sasha born 1998 and 2001.', 'range', 1992, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000d7', 'Items', 'Dreams from My Father / The Audacity of Hope', 'Two bestselling memoirs established him as a literary voice before his presidency; Dreams from My Father was acclaimed for its prose.', 'range', 1995, 2006, '#64748b'),
  ('a0000000-0000-0000-0000-0000000000d7', 'Assets', 'Post-presidency deals', 'Signed a production deal with Netflix (Higher Ground Productions) and a Spotify podcast deal worth tens of millions combined.', 'range', 2018, 2026, '#14b8a6');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000d8', 'Place & Travel', 'Chicago, Illinois', 'Born in Chicago; grew up in Park Ridge suburb; came from a conservative Republican household.', 'range', 1947, 1965, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d8', 'Place & Travel', 'Arkansas', 'Moved to Arkansas in 1975 to follow Bill Clinton; taught law; served as First Lady of Arkansas.', 'range', 1975, 1993, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d8', 'Work & Education', 'Wellesley College / Yale Law School', 'BA from Wellesley 1969 (first student commencement speaker); JD from Yale Law School 1973.', 'range', 1965, 1973, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000d8', 'Work & Education', 'First Lady of the United States', 'First Lady 1993–2001; led healthcare reform effort that failed; faced scrutiny over Whitewater investments.', 'range', 1993, 2001, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000d8', 'Work & Education', 'US Senator from New York', 'Elected Senator from New York in 2000; re-elected 2006; supported the 2002 Iraq War resolution.', 'range', 2001, 2009, '#059669'),
  ('a0000000-0000-0000-0000-0000000000d8', 'Work & Education', 'Secretary of State', 'Served as Secretary of State 2009–2013; oversaw the Arab Spring, Benghazi attack, and the Iran nuclear negotiations.', 'range', 2009, 2013, '#047857'),
  ('a0000000-0000-0000-0000-0000000000d8', 'Work & Education', '2016 Presidential Campaign', 'First woman nominated for president by a major US party; won popular vote by nearly 3 million votes but lost Electoral College.', 'range', 2015, 2016, '#047857'),
  ('a0000000-0000-0000-0000-0000000000d8', 'Relations & Family', 'Married Bill Clinton', 'Married Bill Clinton in Fayetteville, Arkansas in 1975; daughter Chelsea born 1980; remained together through multiple controversies.', 'range', 1975, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000d8', 'Activities', 'Clinton Foundation', 'The Bill, Hillary & Chelsea Clinton Foundation raises funds for global health, education and economic development.', 'range', 2001, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d8', 'Items', 'What Happened (memoir)', 'Published What Happened in 2017, her account of the 2016 election; debuted at number one on the New York Times bestseller list.', 'point', 2017, null, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000d9', 'Place & Travel', 'Hope, Arkansas', 'Born in Hope, Arkansas; grew up in Hot Springs; his Southern working-class background shaped his political appeal.', 'range', 1946, 1968, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d9', 'Place & Travel', 'Oxford and Washington DC', 'Rhodes Scholar at Oxford; attended Georgetown and Yale Law; spent adult career in Arkansas politics then Washington DC.', 'range', 1968, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000d9', 'Work & Education', 'Georgetown / Oxford / Yale Law', 'BS from Georgetown 1968; Rhodes Scholar at Oxford 1968–1970; JD from Yale Law School 1973 where he met Hillary.', 'range', 1964, 1973, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000d9', 'Work & Education', 'Governor of Arkansas', 'Served as Attorney General 1977–1979; Governor of Arkansas 1979–1981 and again 1983–1992 — youngest ever US governor.', 'range', 1977, 1992, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000d9', 'Work & Education', '42nd President of the USA', 'Served two terms 1993–2001; presided over an economic boom; passed NAFTA; intervened militarily in Bosnia and Kosovo.', 'range', 1993, 2001, '#047857'),
  ('a0000000-0000-0000-0000-0000000000d9', 'Activities', 'Impeachment', 'Impeached by the House of Representatives in 1998 over perjury and obstruction related to his affair with Monica Lewinsky; acquitted by the Senate.', 'point', 1998, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000d9', 'Activities', 'Welfare reform and budget surplus', 'Signed the Personal Responsibility Act (welfare reform) in 1996; achieved the first US budget surplus in 30 years.', 'range', 1996, 2001, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000d9', 'Relations & Family', 'Married Hillary Rodham', 'Married in Fayetteville, Arkansas in 1975; daughter Chelsea born 1980; the Monica Lewinsky affair publicly acknowledged 1998.', 'range', 1975, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000d9', 'Health', 'Heart surgery', 'Underwent quadruple bypass heart surgery in 2004 and additional procedures; became a prominent advocate for healthy eating.', 'range', 2004, 2005, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000d9', 'Items', 'My Life (memoir)', 'Published 957-page memoir My Life in 2004; became a bestseller despite mixed critical reception.', 'point', 2004, null, '#64748b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000da', 'Place & Travel', 'New Haven, Connecticut', 'Born in New Haven while his father was attending Yale; family relocated to Texas where he grew up in Midland and Houston.', 'range', 1946, 1968, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000da', 'Place & Travel', 'Texas', 'Texas is his home state; served as Governor then owned the Texas Rangers; his Crawford ranch became a symbol of his presidency.', 'range', 1975, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000da', 'Work & Education', 'Yale / Harvard Business School', 'BA History from Yale 1968; MBA from Harvard Business School 1975; both via legacy admissions.', 'range', 1964, 1975, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000da', 'Work & Education', 'Governor of Texas', 'Won the Texas gubernatorial election in 1994; re-elected 1998; executed a record 152 prisoners during his tenure.', 'range', 1995, 2000, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000da', 'Work & Education', '43rd President of the USA', 'Won disputed 2000 election against Al Gore; served two terms 2001–2009; presidency dominated by 9/11 response and Iraq War.', 'range', 2001, 2009, '#047857'),
  ('a0000000-0000-0000-0000-0000000000da', 'Activities', 'Response to 9/11 and Afghanistan War', 'Led the US response to the September 11 attacks; launched Operation Enduring Freedom in Afghanistan in October 2001.', 'range', 2001, 2003, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000da', 'Activities', 'Iraq War', 'Led the 2003 invasion of Iraq based on intelligence assessments of WMD that later proved inaccurate; destabilised the region.', 'range', 2003, 2009, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000da', 'Activities', 'Response to Hurricane Katrina', 'His administration''s slow response to Hurricane Katrina in 2005 damaged his approval ratings severely.', 'point', 2005, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000da', 'Relations & Family', 'Married Laura Bush', 'Married librarian Laura Welch in 1977; twin daughters Barbara and Jenna born in 1981.', 'range', 1977, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000da', 'Health', 'Alcoholism recovery', 'Acknowledged alcohol abuse in his younger years; became sober in 1986 and a born-again Christian, central to his later identity.', 'range', 1986, 2026, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000da', 'Activities', 'Post-presidency painting', 'Took up painting after leaving office; painted portraits of veterans and world leaders; had successful gallery exhibitions.', 'range', 2012, 2026, '#d97706');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000db', 'Place & Travel', 'Milton, Massachusetts', 'Born in Milton; grew up in Greenwich, Connecticut; an elite New England background shaped by wealth and public service.', 'range', 1924, 1942, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000db', 'Place & Travel', 'Texas and Washington DC', 'Moved to Texas to work in the oil industry after Yale; spent most of his career in Washington or representing Texas.', 'range', 1948, 2018, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000db', 'Work & Education', 'Yale University', 'Enrolled at Yale on return from WWII; graduated in 2.5 years with a degree in economics; Phi Beta Kappa.', 'range', 1945, 1948, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000db', 'Work & Education', 'Military and oil career then politics', 'Youngest naval aviator in WWII; Texas oil businessman; Congressman; UN Ambassador; CIA Director; VP under Reagan.', 'range', 1948, 1988, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000db', 'Work & Education', '41st President of the USA', 'Served one term 1989–1993; oversaw the end of the Cold War, German reunification, and the Gulf War (Desert Storm).', 'range', 1989, 1993, '#047857'),
  ('a0000000-0000-0000-0000-0000000000db', 'Activities', 'Gulf War / Desert Storm', 'Built and led a 35-nation coalition that expelled Iraqi forces from Kuwait in Operation Desert Storm in 1991.', 'range', 1990, 1991, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000db', 'Activities', 'WWII naval service', 'Enlisted on his 18th birthday; flew 58 combat missions; shot down over the Pacific and rescued by a US submarine in 1944.', 'range', 1942, 1945, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000db', 'Relations & Family', 'Married Barbara Pierce', 'Married Barbara Pierce in January 1945; they were together for 73 years — the longest presidential marriage in US history.', 'range', 1945, 2018, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000db', 'Health', 'Vascular Parkinsonism', 'Diagnosed with a Parkinson''s-like condition; used a motorised scooter and wheelchair in later years; died at 94 in 2018.', 'range', 2012, 2018, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000dc', 'Place & Travel', 'Tampico, Illinois', 'Born in Tampico; grew up in Dixon, Illinois; described his Midwestern small-town upbringing as formative to his values.', 'range', 1911, 1932, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000dc', 'Place & Travel', 'California', 'Moved to Los Angeles in 1937 for acting; California became his home base; Governor 1967–1975; buried at his Simi Valley ranch.', 'range', 1937, 2004, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000dc', 'Work & Education', 'Eureka College', 'Attended Eureka College in Illinois on a partial scholarship; played football; majored in economics and sociology.', 'range', 1928, 1932, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000dc', 'Work & Education', 'Actor and Screen Actors Guild president', 'Starred in over 50 Hollywood films; served as SAG president 1947–1952; shifted from New Deal Democrat to Republican.', 'range', 1937, 1966, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000dc', 'Work & Education', 'Governor of California', 'Served as 33rd Governor of California 1967–1975; tough on student protests; welfare reforms.', 'range', 1967, 1975, '#059669'),
  ('a0000000-0000-0000-0000-0000000000dc', 'Work & Education', '40th President of the USA', 'Served two terms 1981–1989; implemented supply-side economics; built up the military; presided over Cold War''s end.', 'range', 1981, 1989, '#047857'),
  ('a0000000-0000-0000-0000-0000000000dc', 'Health', 'Assassination attempt', 'Shot in the chest by John Hinckley Jr. outside a Washington hotel in March 1981; recovered fully.', 'point', 1981, null, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000dc', 'Health', 'Alzheimer''s disease', 'Diagnosed with Alzheimer''s in 1994; wrote a public letter to the American people; declined until his death in 2004.', 'range', 1994, 2004, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000dc', 'Relations & Family', 'Married Jane Wyman then Nancy Davis', 'First marriage to actress Jane Wyman 1940–1949; second to actress Nancy Davis in 1952; devoted partnership.', 'range', 1940, 2004, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000dc', 'Activities', 'Iran-Contra affair', 'His administration secretly sold arms to Iran and illegally diverted profits to Nicaraguan Contras; major scandal.', 'range', 1986, 1987, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000dc', 'Activities', 'Berlin Wall speech', 'Delivered "Mr Gorbachev, tear down this wall!" at the Brandenburg Gate in 1987 — one of the Cold War''s defining moments.', 'point', 1987, null, '#d97706');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000dd', 'Place & Travel', 'Plains, Georgia', 'Born and raised in Plains; returned there after his presidency; remains a defining figure in the small community.', 'range', 1924, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000dd', 'Work & Education', 'US Naval Academy / Navy', 'Graduated from the United States Naval Academy in 1946; served in the Navy including in submarine service under Admiral Hyman Rickover.', 'range', 1942, 1953, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000dd', 'Work & Education', 'Georgia Governor and 39th President', 'Governor of Georgia 1971–1975; President 1977–1981; negotiated the Camp David Accords between Israel and Egypt.', 'range', 1971, 1981, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000dd', 'Activities', 'Camp David Accords', 'Brokered the 1978 peace agreement between Anwar Sadat and Menachem Begin — considered his greatest presidential achievement.', 'point', 1978, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000dd', 'Activities', 'Habitat for Humanity', 'Spent decades volunteering with Habitat for Humanity, personally building houses; became the defining image of his post-presidency.', 'range', 1984, 2019, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000dd', 'Activities', 'Nobel Peace Prize', 'Awarded the Nobel Peace Prize in 2002 for his decades of peaceful conflict resolution and human rights advocacy.', 'point', 2002, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000dd', 'Activities', 'Iran hostage crisis', 'The 444-day Iran hostage crisis defined and damaged his presidency; hostages released the day Reagan was inaugurated.', 'range', 1979, 1981, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000dd', 'Relations & Family', 'Married Rosalynn Smith', 'Married his neighbour Rosalynn Smith in 1946; she died in 2023; he was the longest-lived US president, dying at 100.', 'range', 1946, 2024, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000dd', 'Health', 'Cancer diagnosis and recovery', 'Diagnosed with melanoma that had spread to his brain and liver in 2015; treated with immunotherapy and declared cancer-free.', 'range', 2015, 2016, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000f3', 'Place & Travel', 'Leningrad (St. Petersburg), USSR', 'Born in Leningrad; grew up in a communal apartment; studied law at Leningrad State University; KGB career followed.', 'range', 1952, 1985, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000f3', 'Place & Travel', 'Dresden, East Germany', 'Posted to Dresden as a KGB officer 1985–1990; collected intelligence on NATO and West German citizens.', 'range', 1985, 1990, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000f3', 'Place & Travel', 'Moscow', 'Moved to Moscow to work for the Kremlin administration; rose rapidly to become acting President by 1999.', 'range', 1996, 2026, '#0ea5e9'),
  ('a0000000-0000-0000-0000-0000000000f3', 'Work & Education', 'KGB career', 'Served as a KGB intelligence officer for 16 years, reaching the rank of lieutenant colonel before resigning in 1991.', 'range', 1975, 1991, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000f3', 'Work & Education', 'President and Prime Minister of Russia', 'Acting President from December 1999; won elections in 2000, 2004, 2012, 2018, and 2024; served as PM 2008–2012.', 'range', 1999, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000f3', 'Activities', 'Annexation of Crimea', 'Ordered Russian forces to seize Crimea from Ukraine in 2014 following the Maidan revolution; internationally condemned.', 'point', 2014, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000f3', 'Activities', 'Full-scale invasion of Ukraine', 'Launched a large-scale military invasion of Ukraine on 24 February 2022; issued with an ICC arrest warrant in 2023.', 'range', 2022, 2026, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000f3', 'Activities', 'Chechen wars', 'Launched the Second Chechen War in 1999 that destroyed Grozny and established himself as a tough security figure.', 'range', 1999, 2009, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000f3', 'Relations & Family', 'Married Lyudmila Shkrebneva', 'Married in 1983; divorced in 2014; two daughters Mariya and Katerina; his family life closely guarded.', 'range', 1983, 2014, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000f3', 'Health', 'Health speculation', 'Subject of persistent speculation about health, including Parkinson''s, blood cancer, and steroid use; Kremlin denies all reports.', 'range', 2020, 2026, '#ef4444'),
  ('a0000000-0000-0000-0000-0000000000f3', 'Activities', 'Judo and martial arts', 'Holds a black belt in judo and has cultivated a macho public image; co-authored a judo textbook.', 'range', 1965, 2026, '#d97706');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000f4', 'Place & Travel', 'Beijing, China', 'Born in Beijing to a revolutionary family; father Xi Zhongxun was a senior CCP official later purged during Cultural Revolution.', 'range', 1953, 1969, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000f4', 'Place & Travel', 'Liangjiahe village, Shaanxi', 'Sent to live and work as a peasant in a rural cave village during the Cultural Revolution for seven years; a formative hardship.', 'range', 1969, 1975, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000f4', 'Work & Education', 'Tsinghua University', 'Studied Chemical Engineering at Tsinghua in the 1970s; later obtained a law doctorate in Marxist theory and education from Tsinghua.', 'range', 1975, 1979, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000f4', 'Work & Education', 'Provincial career — Hebei, Fujian, Zhejiang, Shanghai', 'Held a series of provincial party positions; Governor and Party Secretary of Fujian province and Zhejiang province.', 'range', 1982, 2007, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000f4', 'Work & Education', 'General Secretary and President', 'Became General Secretary of the CCP in 2012 and President of China in 2013; had term limits removed in 2018.', 'range', 2012, 2026, '#047857'),
  ('a0000000-0000-0000-0000-0000000000f4', 'Activities', 'Belt and Road Initiative', 'Launched the Belt and Road Initiative in 2013 — a trillion-dollar global infrastructure investment programme.', 'range', 2013, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000f4', 'Activities', 'Crackdown on Uyghurs and Hong Kong', 'Oversaw detention of over one million Uyghurs in Xinjiang and passage of the national security law ending Hong Kong autonomy.', 'range', 2017, 2026, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000f4', 'Relations & Family', 'Married Peng Liyuan', 'Married famous folk singer Peng Liyuan in 1987; she is a major general in the PLA and a prominent public figure.', 'range', 1987, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-0000000000f4', 'Activities', 'Anti-corruption campaign', 'Launched a sweeping anti-corruption campaign from 2012 that disciplined over 1.5 million party officials and removed rivals.', 'range', 2012, 2026, '#f59e0b');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000f5', 'Place & Travel', 'Amiens, France', 'Born in Amiens in northern France; attended the prestigious Lycée Henri-IV in Paris.', 'range', 1977, 1994, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000f5', 'Place & Travel', 'Paris', 'Studied philosophy and political science in Paris; attended Sciences Po and ENA; spent his career in Paris.', 'range', 1994, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000f5', 'Work & Education', 'Sciences Po and ENA', 'Studied Philosophy at Paris Nanterre; graduated Sciences Po; graduated from ENA (Ecole Nationale d''Administration) 2004.', 'range', 1994, 2004, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000f5', 'Work & Education', 'Rothschild banker and Economy Minister', 'Investment banker at Rothschild & Co.; appointed Deputy Secretary-General of the Élysée under Hollande; Economy Minister 2014–2016.', 'range', 2004, 2016, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000f5', 'Work & Education', 'President of France', 'Founded En Marche! centrist movement in 2016; elected youngest French President at age 39 in 2017; re-elected 2022.', 'range', 2017, 2026, '#047857'),
  ('a0000000-0000-0000-0000-0000000000f5', 'Activities', 'Yellow Vest protests', 'His government faced the Gilets Jaunes (Yellow Vest) mass protests from 2018 over fuel taxes and inequality.', 'range', 2018, 2019, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000f5', 'Activities', 'Ukraine diplomatic engagement', 'Took a prominent role in European diplomacy over Ukraine, maintaining dialogue with Putin while supporting Kyiv.', 'range', 2022, 2026, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000f5', 'Relations & Family', 'Married Brigitte Trogneux', 'Met his drama teacher Brigitte Trogneux at age 15; married in 2007; she is 24 years his senior.', 'range', 2007, 2026, '#ec4899');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-0000000000ff', 'Place & Travel', 'Vadnagar, Gujarat, India', 'Born in Vadnagar; grew up in modest circumstances; father ran a tea stall at the railway station.', 'range', 1950, 1967, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000ff', 'Place & Travel', 'Gujarat and New Delhi', 'Built political career in Gujarat; served as Chief Minister of Gujarat 2001–2014 then moved to New Delhi as Prime Minister.', 'range', 1967, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-0000000000ff', 'Work & Education', 'Political science degree', 'Completed a BA in Political Science from Delhi University by correspondence and later an MA from Gujarat University.', 'range', 1978, 1983, '#8b5cf6'),
  ('a0000000-0000-0000-0000-0000000000ff', 'Work & Education', 'RSS and BJP organiser', 'Joined the Rashtriya Swayamsevak Sangh (RSS) as a child; became a full-time BJP organiser in Gujarat in the 1980s.', 'range', 1967, 2001, '#10b981'),
  ('a0000000-0000-0000-0000-0000000000ff', 'Work & Education', 'Chief Minister of Gujarat', 'Served as Chief Minister 2001–2014; his tenure included the controversial 2002 Gujarat riots and rapid economic development.', 'range', 2001, 2014, '#059669'),
  ('a0000000-0000-0000-0000-0000000000ff', 'Work & Education', 'Prime Minister of India', 'Elected PM in 2014 landslide; re-elected 2019 and 2024; pursued Hindu nationalist policies and economic modernisation.', 'range', 2014, 2026, '#047857'),
  ('a0000000-0000-0000-0000-0000000000ff', 'Activities', 'Demonetisation', 'Announced the sudden demonetisation of 500 and 1000 rupee notes in 2016 to combat corruption and black money; caused widespread disruption.', 'point', 2016, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-0000000000ff', 'Activities', 'Ram Mandir inauguration', 'Presided over the inauguration of the Ram Mandir in Ayodhya in January 2024 — a landmark moment for Hindu nationalists.', 'point', 2024, null, '#d97706'),
  ('a0000000-0000-0000-0000-0000000000ff', 'Relations & Family', 'Married Jashodaben Chimanlal Modi', 'Had an arranged marriage at age 17 but left his wife to pursue RSS work; acknowledged the marriage publicly only in 2014.', 'range', 1968, 1968, '#ec4899');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000109', 'Place & Travel', 'Istanbul, Turkey', 'Born in the Kasımpaşa neighbourhood of Istanbul; grew up in a working-class religious family; sold simits on the street as a child.', 'range', 1954, 1976, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000109', 'Work & Education', 'Marmara University', 'Graduated from Marmara University Faculty of Business Administration in 1981.', 'range', 1976, 1981, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000109', 'Work & Education', 'Mayor of Istanbul', 'Elected Mayor of Istanbul in 1994; modernised infrastructure; briefly imprisoned for reciting a religious poem seen as incitement.', 'range', 1994, 1998, '#10b981'),
  ('a0000000-0000-0000-0000-000000000109', 'Work & Education', 'Prime Minister and President of Turkey', 'Co-founded the AKP in 2001; Prime Minister 2003–2014; President 2014–present; gained sweeping executive powers in 2017 referendum.', 'range', 2003, 2026, '#047857'),
  ('a0000000-0000-0000-0000-000000000109', 'Activities', '2016 coup attempt', 'Survived an attempted military coup in July 2016; used it to conduct purges of over 150,000 civil servants, military and academics.', 'point', 2016, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000109', 'Activities', 'Syria intervention', 'Launched multiple military operations into northern Syria against Kurdish YPG forces, creating a security zone.', 'range', 2016, 2026, '#d97706'),
  ('a0000000-0000-0000-0000-000000000109', 'Relations & Family', 'Married Emine Gülbaran', 'Married in 1978; four children; his wife is known for her traditional conservative style and charity work.', 'range', 1978, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000109', 'Health', 'Health rumours', 'Subject of persistent speculation about his health, including reports of bowel cancer; Erdogan has denied all serious illness.', 'range', 2022, 2026, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000010a', 'Place & Travel', 'Kryvyi Rih, Ukraine', 'Born and raised in the industrial city of Kryvyi Rih in central Ukraine; grew up in a Russian-speaking Jewish family.', 'range', 1978, 1995, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010a', 'Place & Travel', 'Kyiv, Ukraine', 'Moved to Kyiv to pursue his entertainment and later political career; remained in the city after Russia''s 2022 invasion.', 'range', 1995, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000010a', 'Work & Education', 'Kyiv National Economic University', 'Studied Law at Kyiv National Economic University; graduated 2000; never practised law, preferring entertainment.', 'range', 1995, 2000, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000010a', 'Work & Education', 'Comedian and actor', 'Co-founded Kvartal 95 comedy studio; starred in Servant of the People TV series as a fictional president of Ukraine.', 'range', 1997, 2019, '#10b981'),
  ('a0000000-0000-0000-0000-00000000010a', 'Work & Education', 'President of Ukraine', 'Elected President in 2019 with 73% of the vote; transformed from comedian to wartime leader after Russia''s 2022 invasion.', 'range', 2019, 2026, '#047857'),
  ('a0000000-0000-0000-0000-00000000010a', 'Activities', 'Leading Ukraine''s war resistance', 'Chose to remain in Kyiv after Russia''s full-scale invasion; his video addresses rallied international support.', 'range', 2022, 2026, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000010a', 'Activities', 'International diplomatic campaign', 'Addressed the UN, US Congress, UK Parliament, EU, and dozens of world leaders; mobilised over $200 billion in Western aid.', 'range', 2022, 2026, '#d97706'),
  ('a0000000-0000-0000-0000-00000000010a', 'Relations & Family', 'Married Olena Kiyashko', 'Met at university; married in 2003; two children; Olena became a prominent figure in Ukraine''s wartime humanitarian campaign.', 'range', 2003, 2026, '#ec4899');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000101', 'Place & Travel', 'Hamilton, New Zealand', 'Born in Hamilton; grew up in Murupara and Morrinsville; raised in a Mormon family though later left the faith.', 'range', 1980, 1999, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000101', 'Place & Travel', 'Wellington, New Zealand', 'Studied at Victoria University of Wellington; worked for Tony Blair''s Cabinet Office in London before returning to NZ politics.', 'range', 1999, 2026, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000101', 'Work & Education', 'Victoria University of Wellington', 'BA in Communication Studies 2001; elected president of the IUSY (International Union of Socialist Youth) while studying.', 'range', 1999, 2001, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000101', 'Work & Education', 'Labour MP and Prime Minister', 'Elected to parliament at 28; became Labour leader 2017; PM at 37 — the world''s youngest female head of government at the time.', 'range', 2008, 2023, '#10b981'),
  ('a0000000-0000-0000-0000-000000000101', 'Activities', 'Christchurch mosque attacks response', 'Led New Zealand''s compassionate response to the March 2019 mosque shootings; rapidly introduced gun law reform.', 'point', 2019, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000101', 'Activities', 'COVID-19 response', 'New Zealand''s early elimination strategy was widely praised internationally; one of the most effective pandemic responses.', 'range', 2020, 2021, '#d97706'),
  ('a0000000-0000-0000-0000-000000000101', 'Relations & Family', 'Partner Clarke Gayford, daughter Neve', 'Partner TV presenter Clarke Gayford; daughter Neve born 2018 — became only the second elected world leader to give birth in office.', 'range', 2018, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000101', 'Work & Education', 'Resignation', 'Resigned as Prime Minister in January 2023 citing burnout and her need to be present for her family.', 'point', 2023, null, '#10b981');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000011c', 'Place & Travel', 'Mayfair, London', 'Born in Mayfair to the Duke and Duchess of York; accession was unexpected until her uncle Edward VIII abdicated.', 'range', 1926, 1939, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000011c', 'Place & Travel', 'Windsor Castle (wartime)', 'Evacuated to Windsor Castle during WWII; made her first radio address to children at age 14; served in the ATS.', 'range', 1939, 1947, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000011c', 'Place & Travel', 'Buckingham Palace and Royal estates', 'Primary residences included Buckingham Palace, Windsor Castle, Balmoral, and Sandringham throughout her reign.', 'range', 1952, 2022, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000011c', 'Work & Education', 'Queen of the United Kingdom', 'Acceded to the throne on 6 February 1952 aged 25 following her father George VI''s death; reigned for 70 years.', 'range', 1952, 2022, '#10b981'),
  ('a0000000-0000-0000-0000-00000000011c', 'Activities', 'Coronation', 'Coronation at Westminster Abbey on 2 June 1953; the first coronation to be televised; watched by 27 million in the UK.', 'point', 1953, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000011c', 'Activities', 'Platinum Jubilee', 'Celebrated 70 years on the throne in June 2022 with national celebrations; died at Balmoral on 8 September 2022.', 'point', 2022, null, '#d97706'),
  ('a0000000-0000-0000-0000-00000000011c', 'Relations & Family', 'Married Prince Philip', 'Married Prince Philip Mountbatten at Westminster Abbey in 1947; together for 73 years; four children.', 'range', 1947, 2021, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000011c', 'Relations & Family', 'Diana and Harry-Meghan controversies', 'Navigated the death of Princess Diana in 1997 and later the Sussexes'' departure from royal duties in 2020.', 'range', 1997, 2022, '#db2777'),
  ('a0000000-0000-0000-0000-00000000011c', 'Activities', 'Commonwealth Headship', 'Served as Head of the Commonwealth for her entire reign, visiting 117 countries and maintaining the organisation.', 'range', 1952, 2022, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000011c', 'Health', 'Death at Balmoral', 'Died peacefully at Balmoral Castle on 8 September 2022; state funeral at Westminster Abbey watched by millions worldwide.', 'point', 2022, null, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-000000000121', 'Place & Travel', 'Sandringham, Norfolk', 'Born at Park House on the Sandringham Estate; grew up in English country houses; parents divorced when she was seven.', 'range', 1961, 1980, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000121', 'Place & Travel', 'London', 'Moved to London in her late teens; worked as a nursery school assistant; lived in Kensington Palace throughout her marriage.', 'range', 1979, 1997, '#3b82f6'),
  ('a0000000-0000-0000-0000-000000000121', 'Place & Travel', 'Paris — fatal crash', 'Died in a car crash in the Pont de l''Alma tunnel in Paris on 31 August 1997 while being pursued by paparazzi.', 'point', 1997, null, '#0ea5e9'),
  ('a0000000-0000-0000-0000-000000000121', 'Work & Education', 'Princess of Wales', 'Married Prince Charles at St Paul''s Cathedral on 29 July 1981; watched by 750 million people worldwide.', 'range', 1981, 1996, '#8b5cf6'),
  ('a0000000-0000-0000-0000-000000000121', 'Activities', 'Landmine campaign', 'Campaigned globally against landmines; walked through minefields in Angola and Bosnia; the Ottawa Treaty was signed months after her death.', 'range', 1996, 1997, '#f59e0b'),
  ('a0000000-0000-0000-0000-000000000121', 'Activities', 'AIDS activism', 'Shook hands with AIDS patients on camera at a time when many feared casual contact; did more than anyone to destigmatise the disease.', 'range', 1987, 1997, '#d97706'),
  ('a0000000-0000-0000-0000-000000000121', 'Relations & Family', 'Married Prince Charles', 'Married 1981; marriage deteriorated amid both parties'' affairs; separated 1992; divorced August 1996.', 'range', 1981, 1996, '#ec4899'),
  ('a0000000-0000-0000-0000-000000000121', 'Relations & Family', 'Sons William and Harry', 'Sons Prince William born 1982 and Prince Harry born 1984; her parenting style was unusually hands-on for the Royal Family.', 'range', 1982, 1997, '#db2777'),
  ('a0000000-0000-0000-0000-000000000121', 'Health', 'Eating disorder and mental health', 'Spoke openly about her bulimia and depression in a 1995 Panorama interview seen by 23 million viewers in the UK.', 'range', 1983, 1997, '#ef4444');
INSERT INTO public.persona_events (persona_id, lane_name, title, description, type, start_year, end_year, color) VALUES
  ('a0000000-0000-0000-0000-00000000011f', 'Place & Travel', 'London and Eton', 'Born at St Mary''s Hospital; raised in Kensington Palace and Highgrove; attended Eton College.', 'range', 1984, 2005, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000011f', 'Place & Travel', 'Afghanistan (two tours)', 'Served two tours in Afghanistan with the British Army; first as a forward air controller and second as an Apache helicopter pilot.', 'range', 2007, 2013, '#3b82f6'),
  ('a0000000-0000-0000-0000-00000000011f', 'Place & Travel', 'Montecito, California', 'Moved to California with Meghan Markle in 2020 after stepping back from senior royal duties.', 'range', 2020, 2026, '#0ea5e9'),
  ('a0000000-0000-0000-0000-00000000011f', 'Work & Education', 'Royal Military Academy Sandhurst', 'Graduated from Sandhurst in 2006; commissioned as a second lieutenant; served in the Blues and Royals.', 'range', 2005, 2015, '#8b5cf6'),
  ('a0000000-0000-0000-0000-00000000011f', 'Work & Education', 'Invictus Games founder', 'Founded the Invictus Games in 2014 for wounded and sick armed forces personnel and veterans; now held globally.', 'range', 2014, 2026, '#10b981'),
  ('a0000000-0000-0000-0000-00000000011f', 'Activities', 'Megxit — stepping back from royal duties', 'Announced with Meghan in January 2020 they would step back from senior royal duties; moved to Canada then California.', 'point', 2020, null, '#f59e0b'),
  ('a0000000-0000-0000-0000-00000000011f', 'Activities', 'Oprah interview and Netflix series', 'A 2021 Oprah interview and Netflix docuseries made serious allegations about the Royal Family and racism concerns.', 'range', 2021, 2023, '#d97706'),
  ('a0000000-0000-0000-0000-00000000011f', 'Relations & Family', 'Married Meghan Markle', 'Married American actress Meghan Markle at Windsor Castle in May 2018; son Archie born 2019, daughter Lilibet born 2021.', 'range', 2018, 2026, '#ec4899'),
  ('a0000000-0000-0000-0000-00000000011f', 'Health', 'Mental health advocacy', 'Has spoken openly about PTSD, grief over his mother''s death, and mental health struggles; co-founded Heads Together with William.', 'range', 2016, 2026, '#ef4444'),
  ('a0000000-0000-0000-0000-00000000011f', 'Items', 'Spare (memoir)', 'Published memoir Spare in January 2023; became the fastest-selling non-fiction book in UK history with explosive revelations.', 'point', 2023, null, '#64748b');
